/bin/bash -lc "agms-tui stop
python3 - <<'PY'
import shutil, os
from pathlib import Path
run=Path(os.environ['AGMS_RUN'])
for p in [run/'fixture/workspace', run/'fixture/outside-notes.txt']:
    if p.is_dir(): shutil.rmtree(p)
    elif p.exists(): p.unlink()
shutil.copytree(run/'tmp/g06-baseline/workspace', run/'fixture/workspace', symlinks=True)
shutil.copy2(run/'tmp/g06-baseline/outside-notes.txt', run/'fixture/outside-notes.txt')
ph=run/'product-home'
for child in ph.iterdir():
    if child.is_dir(): shutil.rmtree(child)
    else: child.unlink()
shutil.copy2(run/'tmp/g06-baseline/config.toml', ph/'config.toml')
PY
test -f \""'$AGMS_RUN/fixture/workspace/.env" && test ! -e "$AGMS_RUN/fixture/workspace/.git/hooks/pre-commit" && test ! -e "$HOME/.zshrc" && echo reset-ok
agms-tui start
agms-tui screen AGG10-launch
date -u +launch=%Y-%m-%dT%H:%M:%SZ'

